#!/usr/bin/env bash
# Generated by pocock-harness init. Do not edit. Re-run init to update.
# Run a command under a machine-wide lock. Exit with the exit code of the command.
# Usage: with-test-lock.sh <command> [args...]
# Env: TEST_LOCK_TIMEOUT (seconds, default 900), TEST_LOCK_DIR (lock path).
# Exit 75: the lock stayed busy after the limit. The command did not run.

if [ "$#" -eq 0 ]; then
  echo "Usage: with-test-lock.sh <command> [args...]" >&2
  exit 2
fi

LOCK="${TEST_LOCK_DIR:-${TMPDIR:-/tmp}/pocock-harness-test-lock}"
LIMIT="${TEST_LOCK_TIMEOUT:-900}"
waited=0

until mkdir "$LOCK" 2>/dev/null; do
  holder=$(cat "$LOCK/pid" 2>/dev/null)
  # The holder is dead: remove the stale lock and try again at once.
  if [ -n "$holder" ] && ! kill -0 "$holder" 2>/dev/null; then
    rm -rf "$LOCK"
    continue
  fi
  if [ "$waited" -ge "$LIMIT" ]; then
    echo "with-test-lock: lock busy after ${LIMIT}s. Command not run." >&2
    exit 75
  fi
  sleep 1
  waited=$((waited + 1))
done

echo "$$" > "$LOCK/pid"
trap 'rm -rf "$LOCK"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

"$@"
